def shortest_palindrome(s):
    for L in range(len(s), 0, -1):
        if s[:L] == s[:L][::-1]:
            return s[L:][::-1] + s
    return s

def shortest_palindrome(s):
    t = s + "#" + s[::-1]
    pi, k = [0] * len(t), 0
    for i in range(1, len(t)):
        while k and t[i] != t[k]:
            k = pi[k - 1]
        if t[i] == t[k]:
            k += 1
        pi[i] = k
    return s[pi[-1]:][::-1] + s
